type Claims = readonly [string, string, string, string];

export interface KnowledgeEvidence {
  stem: string;
  claims: Claims;
  valid: string;
  explanation: string;
}

function evidence(stem: string, claims: Claims, valid: string, explanation: string): KnowledgeEvidence {
  return { stem, claims, valid, explanation };
}

